<?php
namespace App\Controllers; use App\Services\BayerDataService;
class ApiController {private function guard():void{if(!\config('app.api_enabled')){$this->respond(['error'=>'API deshabilitada'],503);} $auth=$_SERVER['HTTP_AUTHORIZATION']??'';$token=preg_replace('/^Bearer\s+/i','',$auth);if(!$token || !hash_equals((string)\config('app.api_token'),$token))$this->respond(['error'=>'No autorizado'],401);}private function respond(array $d,int $s=200):never{http_response_code($s);header('Content-Type: application/json; charset=utf-8');echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);exit;}public function sales():void{$this->guard();$this->respond(['data'=>(new BayerDataService())->sales()]);}public function shipments():void{$this->guard();$this->respond(['data'=>(new BayerDataService())->shipments()]);}public function inventory():void{$this->guard();$this->respond(['data'=>(new BayerDataService())->inventory()]);}}
